using System;
class SpellStatusChecks {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Main(){var c=new CombatState();c.ApplyPlayerDamage(2);c.ApplyDamage(2);c.BlockHealing(true);c.BlockHealing(false);Check(c.HealPlayer(2)==0&&c.HealMonster(2)==0,"healing prevention");c.ExpirePlayerTurnEffects();Check(c.PlayerHealingBlocked&&c.MonsterHealingBlocked,"effect survives casting turn end");c.EndRound();Check(c.PlayerHealingBlocked,"effect survives next turn start");c.ExpirePlayerTurnEffects();Check(c.HealPlayer(2)==2&&c.HealMonster(2)==2,"effect expires next turn end");c.ApplyMockery(false);Check(c.ConsumeMockery(false)&&!c.ConsumeMockery(false),"mockery consumed once");c.ApplyMockery(false);c.FinishMonsterTurnEffects();Check(!c.ConsumeMockery(false),"unused mockery expires monster turn end");c.ApplyMockery(true);c.ExpirePlayerTurnEffects();c.EndRound();Check(c.ConsumeMockery(true),"player mockery survives until next turn");c.ApplyMockery(true);c.ClearShortDurationEffects();Check(!c.ConsumeMockery(true)&&!c.PlayerHealingBlocked,"rest clears short effects");c.BlockHealing(true);c.GrantPlayerTemporaryHp(8);Check(c.PlayerTemporaryHp==8,"temporary hp not healing");c.GrantPlayerTemporaryHp(4);Check(c.PlayerTemporaryHp==8,"temporary hp do not stack");c.ResetBattle();Check(!c.PlayerHealingBlocked&&!c.MonsterHealingBlocked&&c.PlayerTemporaryHp==0,"reset clears effects");Check(DirectSpell.Find("Magic Missile").DiceCount(1,1)==3&&DirectSpell.Find("Magic Missile").DiceCount(20,9)==11,"magic missile upcasting independent of character level");c.ApplyFrostSlow(false);Check(c.MonsterSpeed==20,"frost reduces monster speed");c.ApplyFrostSlow(true);c.BlockOpportunity(false);c.BlockOpportunity(true);Check(c.TryUseReaction(true),"shocking grasp preserves other reactions");c.StartMonsterTurn();Check(!c.MonsterOpportunityBlocked&&c.PlayerOpportunityBlocked,"monster opportunity lock expires at monster start");c.EndRound();Check(!c.PlayerSlowed&&!c.MonsterSlowed&&!c.PlayerOpportunityBlocked&&c.MonsterSpeed==30,"frost and player opportunity lock expire at player start");c.ResetBattle();c.SetPlayerArmorOverride(12);c.ActivateShield();Check(c.PlayerArmorClass==17&&c.ShieldActive,"shield adds to beast armor");c.EndRound();Check(c.PlayerArmorClass==12&&!c.ShieldActive,"shield expires at next player start");c.ActivateShield();c.ResetBattle();Check(c.PlayerArmorClass==10&&!c.ShieldActive,"reset clears shield");Check(DirectSpell.Find("Thunderwave").DiceCount(1,1)==2&&DirectSpell.Find("Thunderwave").DiceCount(1,9)==10,"thunderwave upcast dice");Check(DirectSpell.Find("Thunderclap").DiceCount(17,1)==4&&DirectSpell.Find("Word of Radiance").SaveAbility==2,"emanation cantrip scaling and constitution save");c.ApplyGuidingLight(false);Check(c.ConsumeGuidingLight(false)&&!c.ConsumeGuidingLight(false),"guiding light consumed once");c.ApplyGuidingLight(true);c.ExpirePlayerTurnEffects();c.EndRound();Check(c.ConsumeGuidingLight(true),"guiding light survives next turn start");c.ApplyGuidingLight(false);c.ExpirePlayerTurnEffects();c.EndRound();c.ExpirePlayerTurnEffects();Check(!c.ConsumeGuidingLight(false),"guiding light expires next caster turn end");Check(DirectSpell.Find("Blight").DiceCount(1,4)==8&&DirectSpell.Find("Blight").DiceCount(1,9)==13,"blight upcast");Check(DirectSpell.Find("Guiding Bolt").DiceCount(1,1)==4&&DirectSpell.Find("Guiding Bolt").DiceCount(1,9)==12,"guiding bolt upcast");Check(DirectSpell.Find("Scorching Ray").DiceCount(1,2)==3&&DirectSpell.Find("Scorching Ray").DiceCount(20,9)==10,"scorching ray counts");var buffs=new TimedSpellBuffs();buffs.DivineFavor(100);Check(buffs.DivineActive(109)&&!buffs.DivineActive(110),"divine favor duration");buffs.MagicWeapon("sword",2,0);Check(buffs.WeaponBonus("sword",599)==1&&buffs.WeaponBonus("sword",600)==0,"magic weapon hour");buffs.MagicWeapon("bow",3,0);Check(buffs.WeaponBonus("bow",0)==2&&buffs.WeaponBonus("sword",0)==0,"recast replaces previous weapon");buffs.MagicWeapon("sword",6,0);Check(buffs.WeaponBonus("sword",0)==3,"magic weapon high slot");buffs.Longstrider(true,0);buffs.Longstrider(true,10);Check(buffs.SpeedBonus(true,609)==10&&buffs.SpeedBonus(true,610)==0&&buffs.SpeedBonus(false,0)==0,"longstrider no stacking and independent targets");buffs.Clear();Check(!buffs.DivineActive(0)&&buffs.WeaponBonus("sword",0)==0,"buff reset");c.ResetBattle();c.ApplyPoison(true);c.ApplyPoison(false);c.ExpirePlayerTurnEffects();Check(c.PlayerPoisoned&&c.MonsterPoisoned,"poison survives casting turn end");c.EndRound();Check(c.PlayerPoisoned&&c.MonsterPoisoned,"poison survives next turn start");c.ExpirePlayerTurnEffects();Check(!c.PlayerPoisoned&&!c.MonsterPoisoned,"poison expires next caster turn end");c.ApplyPoison(true);c.ResetBattle();Check(!c.PlayerPoisoned,"reset poison");Check(DirectSpell.Find("Eldritch Blast").DiceCount(1,1)==1&&DirectSpell.Find("Eldritch Blast").DiceCount(5,1)==2&&DirectSpell.Find("Eldritch Blast").DiceCount(11,1)==3&&DirectSpell.Find("Eldritch Blast").DiceCount(17,1)==4,"eldritch blast total level beam scaling");Check(DirectSpell.Find("Ray of Sickness").DiceCount(1,1)==2&&DirectSpell.Find("Ray of Sickness").DiceCount(1,9)==10&&DirectSpell.Find("Ray of Sickness").SaveAbility==-1,"sickness upcasting without saving throw");Check(DirectSpell.Find("Hold Monster").AllowsCreatureType(13)&&DirectSpell.Find("Hold Monster").AllowsCreatureType(1)&&!DirectSpell.Find("Hold Person").AllowsCreatureType(13)&&DirectSpell.Find("Hold Person").AllowsCreatureType(9),"2024 hold monster includes undead while hold person requires humanoid");Console.WriteLine("PASS: healing prevention duration, single-use disadvantage, turn expiry, rest, temporary HP and reset");}
}
